#!/usr/bin/env python3
import os
f = open('/app/alpine.iso','rb')
S=2048
def rd(off,n):
    f.seek(off); return f.read(n)
def le32(b,o): return int.from_bytes(b[o:o+4],'little')
root_ext, root_size = 20, 2048
def entries(ext,size):
    res=[]; data=rd(ext*S,size); p=0
    while p < len(data):
        L=data[p]
        if L==0: break
        if L<34:
            p=(p//S+1)*S; continue
        e2=le32(data,p+2); s2=le32(data,p+10); fl=data[p+25]; nl=data[p+32]
        res.append((data[p+33:p+33+nl],e2,s2,fl)); p+=L
    return res
