    seen.add(ext)
    for name,e2,s2,fl in entries(ext,size):
        if name in (b'\x00',b'\x01'): continue
        base=name.split(b';')[0].decode('latin1','replace')
        if fl & 2: walk(e2,s2,path+'/'+base)
        else: files[path+'/'+base]=(e2,s2)
walk(root_ext,root_size,'')
